        + [F("Napakamahal kasing ___. (to ride a plane)", "mag-eroplano", ["magbarko", "magroro"], "mag-eroplano."), F("Pagdating mo sa Dipolog, sumakay ka ng ___. (habal-habal)", "habal-habal", ["eroplano", "barko"], "habal-habal."), F("___ airline ang gusto mo? (Which)", "Aling", ["Alin", "Ano"], "aling + linker."), F("___ ang mura? (Which one)", "Alin", ["Aling", "Ano"], "alin."), F("Matipid at marami ka pang ___ ibang lugar. (will see)", "makikitang", ["makikita", "makita"], "makikitang.")]
