_RV = [("Nasaan ba ang mga bata?", "Na kina Tita po ang mga bata.", "Where are the children? The children are at Auntie’s, sir or ma’am."), ("Taga-Missouri ka ba?", "Hindi po, taga-California po ako.", "Are you from Missouri? No, I am from California.")]
_SN = [("Gusto ko po sanang pumunta ng Dakak sa Dapitan.", "I hope to go to Dakak in Dapitan, sir or ma’am."), ("Napakamahal kasing mag-eroplano.", "It’s because it is too expensive to travel by plane."), ("Mga anim na oras yata.", "It looks like around six hours."), ("Iisipin ko na po muna.", "I will already first think about it, sir or ma’am."), ("Magpapareserba po sana ako ng biyahe mula Maynila papuntang Kalibo.", "I hope to reserve a flight from Manila to Kalibo, sir or ma’am."), ("Sa a-beynte singko na po ang balik.", "The return is already on the twenty-fifth, sir or ma’am."), ("Kasama na po ang buwis.", "The tax is already included, sir or ma’am."), ("Tumatanggap po ba kayo ng credit card?", "Are you accepting credit cards, sir or ma’am?")]
_ENC = [("muna", "first (before something else is done)", "Maghintay ka muna.", "You wait first."), ("muna", "not yet (with the negative huwag or hindi)", "Huwag muna tayong mag-book ng flight.", "Let’s not book a flight yet."), ("sana", "hopefully, I hope or wish", "Sana makarating ang eroplano kaagad.", "I hope the airplane will arrive immediately."), ("sana", "was planning to do something (with the conjunction pero)", "Magbibiyahe sana kami pero umulan nang malakas.", "We hoped to travel but it rained hard."), ("yata", "it looks like, it seems, it appears", "Tiket yata ni Gregorio iyan.", "That looks like Gregorio’s ticket."), ("na", "already, now", "Huli na tayo.", "We are already late."), ("kasi", "because, it is because", "Hindi kami natuloy kasi maulan.", "We did not continue because it was rainy.")]
_NAEX = [("Kumain ka na ba?", "Have you already eaten?"), ("Hindi na ako kumain.", "I did not eat anymore."), ("Dumeretso na ang mga bisita.", "The visitors have already gone straight ahead."), ("Kumain na sina Armand at Hannah.", "Armand and Hannah have already eaten."), ("Kumakain na naman si Dinah.", "Dinah is eating again.")]
_AL = [("Alin ang airline nina Lolo at Lola?", "Which (one) is Grandpa’s and Grandma’s airline?"), ("Alin ang mura?", "Which (one) is cheap?"), ("Alin sa dalawang airline ang on time?", "Which of the two airlines is on time?"), ("Alin sa kanila ang maganda ang serbisyo?", "Which of them has good service?"), ("Alin ang pinili mo?", "Which (one) did you choose?"), ("Aling airline ang gusto mo?", "Which airline do you prefer?")]
L3 = lesson(
    "C10 L1 · The enclitics sana, yata, muna, na and kasi; the question word alin",
    "Sana · Yata · Muna · Na · Kasi · Alin",
    requires=[],
    cards=[
        card("A. The enclitics: review", "We took up some enclitics at the beginning of Semester I. Ho, po and ba are enclitic particles. Po and ho signal politeness and are equivalent to sir/madam; po is more formal and more polite than ho. Ba is an enclitic particle signaling a question. Opo and oho are not enclitics: they are complete words equivalent to a polite “Yes, sir/madam.” To say “No” politely, say Hindi ho.", tables=[table(["Question", "Answer", "Meaning"], [list(r) for r in _RV], say=[0, 1])]),
        card("Culture note: politeness", "Filipinos place great emphasis on politeness and respect for elders. The first words taught to a child are opo and oho. They are also used by adults when addressing anyone older or higher in rank, and when meeting for the first time. Use these words until the person addressed urges you not to; this is a signal that the getting-acquainted stage is progressing to a more familiar level."),
        card("Lesson proper: sentences from the reading (the book’s key)", "Translate these sentences, paying attention to the enclitics.", examples=passage(_SN)),
        card("What each enclitic means", "Sana means “hopefully, I hope or wish.” Yata signifies what on the surface someone or something is, “it seems,” “looks,” “appears”: Uulan yata is “It looks like it will rain”; Siya yata ang piloto is “It seems he or she is the pilot.” Yata never starts a sentence but can be used as a one-word answer: Uulan ba? Yata. (Will it rain? Looks like.) Native speakers say Tila yata (literally “It looks like it seems”). Sometimes yata means something else, as in Ako yata ang bumili niyan: it can be “It seems I was the one who bought that” or “After all, I was the one who bought that”; an exclamation mark instead of a period most definitely means the latter, the emotional meaning of yata. Muna implies “before you do or say something”; even though muna means “first,” it is not a substitute for the ordinal number “first” (una or pang-una, also pangunahin). Kasi means “because, it is because.” Na means “now” or “already” in affirmative sentences, and “anymore” or “not anymore” in negative sentences. Na is used with the past tense to show all the perfect tenses. The combination na naman means “again.”"),
        card("Examples with na", "", examples=passage(_NAEX)),
        card("Summary of the enclitics", "", tables=[table(["Enclitic", "Meaning", "Example", "Translation"], [list(r) for r in _ENC], say=[0, 2])]),
        card("B. The question word alin", "Alin means “which” and signifies a choice, implied or otherwise. The uses with examples from the reading: 1. Alin with nouns and adjectives, followed by ang (Alin ang mura?); 2. Alin with numbers and with personal and demonstrative pronouns, followed by sa (Alin sa dalawang airline ang on time?); 3. Alin with verbs (Alin ang pinili mo?); 4. Alin as a modifier, with the linker (Aling airline ang gusto mo?).", examples=passage(_AL)),
    ],
    exercises=uniq(
        tr_q(_SN) + rev_q(_SN) + tr_q(_NAEX) + rev_q(_NAEX) + tr_q(_AL) + rev_q(_AL) + tr_q([(t, e) for t, _, e in _RV]) + tr_q([(f"{a} {b}", c) for a, b, c in [(x[2], "", x[3]) for x in _ENC]])
        + [M(f"What does {e} mean ({m})?", m, dd([x[1] for x in _ENC], m, extra=["politeness", "question marker"]), f"{e}.") for e, m, ex, tr in _ENC]
        + [M("What does ba signal?", "a yes-or-no question", ["politeness", "a command", "the past tense"], "ba."), M("Which is more formal and polite, po or ho?", "po", ["ho", "they are equal", "neither"], "po."), M("Are opo and oho enclitics?", "No, they are complete words", ["Yes", "Only opo", "Only oho"], "opo, oho."), M("Can yata start a sentence?", "No", ["Yes, always", "Only in questions", "Only in the past"], "yata."), M("What does na naman mean?", "again", ["now", "never", "also"], "na naman."), M("What does na mean in a negative sentence?", "anymore", ["already", "first", "because"], "hindi na."), M("What is the ordinal number “first”?", "una or pang-una", ["muna", "sana", "yata"], "una."), M("Which word means “which” before a noun with a linker?", "aling", ["alin", "anong", "sino"], "aling."), M("Which word follows alin before a noun phrase of two or more?", "sa", ["ang", "ng", "ni"], "alin sa.")]
        + [F("Huwag ___ tayong mag-book ng flight. (yet)", "muna", ["sana", "yata"], "huwag muna."), F("Hindi kami natuloy ___ maulan. (because)", "kasi", ["sana", "muna"], "kasi."), F("Tiket ___ ni Gregorio iyan. (it seems)", "yata", ["muna", "kasi"], "yata."), F("___ makarating ang eroplano kaagad. (I hope)", "Sana", ["Muna", "Kasi"], "sana."), F("Huli ___ tayo. (already)", "na", ["muna", "sana"], "na."), F("___ ang pinili mo? (Which one)", "Alin", ["Aling", "Anong"], "alin.")]
    ),
)

