_VM = [("Andres, puwede ka bang magpareserba ng flight para sa akin?", "Andres, can you reserve a flight for me?"), ("Kailangan ko munang pumunta sa Pilipinas sa lalong madaling panahon, anak.", "I need to go to the Philippines first as soon as possible, child."), ("Tawagan mo ang PAL at kung puwede sa Sabado nang gabi ang alis ng eroplano.", "Call PAL and if possible the plane leaves on Saturday night."), ("Gamitin mo muna ang pera sa joint account natin para sa pambayad ng tiket.", "Use the money in our joint account first to pay for the ticket."), ("O, sige anak, tumawag ka sa akin kapag nakapag-book ka na.", "Okay, child, call me when you have booked.")]
