_P2 = [("A", "Anak, mabuti pa i-cancel mo na lang ang biyahe mo sa Zamboanga.", "Child, it is better to just cancel your trip to Zamboanga."), ("B", "Nay, hindi po puwede. Kaarawan po ni Lolo Goryo. Hindi po puwedeng wala ako.", "Mom, I can’t. It is Grandpa Goryo’s birthday. I can’t be absent."), ("A", "Hindi ka ba natatakot? May bagyo daw bukas. Medyo malakas ang alon, tatlumpu’t anim na oras pa ang biyahe. Matagal-tagal din iyon.", "Aren’t you scared? They say there will be a typhoon tomorrow. The waves are rather strong and the trip is still thirty-six hours. That’s quite long."), ("B", "Mama, ika-cancel naman po ng coastguard ang biyahe kung talagang malakas ang bagyo.", "Mama, the coast guard will cancel the trip if the typhoon is really strong."), ("A", "Ang tigas tigas talaga ng ulo mong bata ka. Mabuti pa mag-eroplano ka na lang ngayong gabi. Mabuti na ang sigurado.", "You really are so hardheaded, child. It is better to just take a plane tonight. Better to be sure.")]
_N1 = [("Taga-Batangas ako. Pero estudyante ako sa Maynila.", "I am from Batangas. But I am a student in Manila."), ("Unang beses kong bumiyahe papuntang Mindanao.", "It is my first time traveling to Mindanao."), ("Field trip namin sa Dapitan, Zamboanga del Norte.", "Our field trip is to Dapitan, Zamboanga del Norte."), ("Unang beses kong sumakay ng eroplano mula Manila papuntang Dipolog.", "It was my first time riding a plane from Manila to Dipolog."), ("Tapos nag-dyip kami mula Dipolog papuntang Dapitan.", "Then we rode a jeepney from Dipolog to Dapitan."), ("Malapit lang, mga dalawampu’t pitong minuto ang biyahe, dalawampu’t isang kilometro lang kasi ang layo.", "It is near, the trip takes about twenty-seven minutes because the distance is only twenty-one kilometers.")]
_N2 = [("Unang beses din akong sumakay ng habal-habal papuntang Dakak.", "It was also my first time riding a habal-habal to Dakak."), ("Walo kami sa isang habal-habal.", "There were eight of us on one habal-habal."), ("Nakakatakot pero masaya.", "It was scary but fun."), ("Maaliwalas ang panahon dahil Disyembre nung bumiyahe kami.", "The weather was clear because it was December when we traveled."), ("Magandang bumiyahe kapag Disyembre.", "It is good to travel in December."), ("Medyo malamig ang hangin. Hindi masyadong mainit.", "The wind is a bit cold. It is not too hot.")]
_C11 = [("A", "Magandang hapon po, magpapabook po sana ako ng flight papuntang Manila.", "Good afternoon, I would like to book a flight to Manila."), ("B", "Saan po galing ma’am?", "Where from, ma’am?"), ("A", "Sa Laoag, Ilocos Norte po.", "From Laoag, Ilocos Norte."), ("B", "Balikan po ba?", "Is it roundtrip?"), ("A", "Papuntang Maynila lang po.", "Only to Manila."), ("B", "Ilan po ang pasahero?", "How many passengers?"), ("A", "Dalawang senior citizen po, isang estudyante, at isang taong gulang na bata.", "Two senior citizens, one student and a one-year-old child."), ("B", "May diyes porsiyentong diskuwento po ang senior citizen at ang estudyante basta may ID lang. Tapos libre po iyong bata.", "Senior citizens and the student get a ten percent discount as long as they have an ID. And the child is free.")]
