_G12 = [("Travel agent", "Magandang umaga po. DDR Travel and Tours po ito. Ano po ang maipaglilingkod ko sa inyo?", "Good morning. This is DDR Travel and Tours. How can I help you?"), ("Client", "Magandang umaga rin po. Gusto ko pong mag-book ng biyahe para sa dalawang tao.", "Good morning too. I would like to book a trip for two people."), ("Travel agent", "Saan po ang pupuntahan ninyo at kailan po ang biyahe?", "Where will you go and when is the trip?"), ("Client", "Papuntang Cebu po. Balikan po para sa dalawa, mula ika-beynte hanggang ika-beynte otso ng Disyembre.", "To Cebu. Roundtrip for two, from the twentieth to the twenty-eighth of December."), ("Travel agent", "Anong oras po ang gusto ninyong bumiyahe?", "What time do you want to travel?"), ("Client", "Sa umaga po, mula alas-singko hanggang alas-diyes. Magkano po lahat?", "In the morning, from five to ten. How much is it altogether?"), ("Travel agent", "Pitong libo limandaan at siyamnapung piso at singkuwenta sentimos po kasama ang buwis.", "Seven thousand five hundred ninety pesos and fifty centavos, tax included."), ("Client", "Tumatanggap po ba kayo ng credit card?", "Do you accept credit cards?"), ("Travel agent", "Opo.", "Yes.")]
_G13 = [("Estudyante", "Magandang umaga po, Ma’am. Balak ko pong pumunta sa Boracay. Ano po ang pinakamurang paraan?", "Good morning, ma’am. I plan to go to Boracay. What is the cheapest way?"), ("Guro", "Magandang umaga rin. Isa ang Boracay sa pinakabinibisita ng mga lokal at dayuhang turista. Puwede kang magroro mula Batangas hanggang Calapan, Oriental Mindoro. Tapos lumipat ka sa isa pang roro papuntang Caticlan, Aklan.", "Good morning too. Boracay is one of the most visited by local and foreign tourists. You can take a roro from Batangas to Calapan, Oriental Mindoro. Then transfer to another roro to Caticlan, Aklan."), ("Estudyante", "Ilang oras po ang biyahe mula Batangas hanggang Aklan?", "How many hours is the trip from Batangas to Aklan?"), ("Guro", "Mga lima at kalahating oras.", "About five and a half hours."), ("Estudyante", "Magkano po?", "How much?"), ("Guro", "Isang libo’t apatnaraang piso lang ang kabuuan para sa first class.", "Only one thousand four hundred pesos in total for first class."), ("Estudyante", "Anong buwan po ang magandang bumisita?", "Which month is good to visit?"), ("Guro", "Kahit anong buwan maliban sa tag-ulan ng Hunyo at Hulyo.", "Any month except the rainy season of June and July."), ("Estudyante", "Salamat po. Iisipin ko po muna.", "Thank you. I will think about it first.")]
