_TS = [("Dahil alas-diyes ang alis ng bus, dumating siya sa istasyon nang alas-nuwebe y medya.", "Because the bus departs at ten o’clock, he arrived at the station at half past nine."), ("Sa Disyembre pa ang balik ko sa States. Magtatagal pa ako dito sa Pinas.", "My return to the States is not until December. I will stay longer here in the Philippines."), ("Kumuha ka ng balikang tiket. Mas matipid iyon.", "Get a roundtrip ticket. That is more economical."), ("Labindalawang oras ang biyahe mula Maynila hanggang Banaue.", "The trip from Manila to Banaue is twelve hours."), ("Kasama na po ang buwis sa halaga ng tiket ninyo.", "Tax is already included in the price of your ticket."), ("Hindi po kasama ang bayad sa drayber kung aarkila kayo ng van.", "The driver’s fee is not included if you rent a van."), ("Magpapa-book na ako ng dalawang kuwarto sa hotel ngayong gabi.", "I will book two rooms at the hotel tonight."), ("Upang makarating sa pulo, kailangan nating sumakay ng bangka.", "To reach the island, we need to ride a boat."), ("Pagdating sa pulo, manananghalian muna tayo.", "Upon arrival at the island, let’s have lunch first."), ("Isa ito sa pinakamalaking paliparan na napuntahan ko.", "This is one of the biggest airports I have been to."), ("Siksikan ang mga turistang pasahero sa roro.", "The tourist passengers are packed in the roro."), ("Walang-walang sinabi ang kalidad ng serbisyo ng Coron Gateway dito sa Busuanga Seadive Hotel.", "The quality of service of Coron Gateway cannot compare with that of the Busuanga Seadive Hotel here."), ("Sumakay kami ng balsa para makarating sa Nagata Falls sa Aklan.", "We rode a raft to reach Nagata Falls in Aklan.")]
_MS = [("Mas matipid ang magbarko kaysa mag-eroplano mula Batangas hanggang Caticlan.", "Riding a ship is more economical than riding a plane from Batangas to Caticlan."), ("Mag-eroplano ka na lang. Hindi naman malaki ang diperensiya sa presyo ng tiket sa barko.", "Just take a plane. The difference in the ticket price to the ship is not big."), ("Puwede ring mag-RORO mula Bicol patungong Kabisayaan at Palawan. Araw-araw ang biyahe, may air-con, higaan, kainan, disco, at bar o sports facilities.", "You can also take a roro from Bicol to the Visayas and Palawan. The trip is daily, with air-conditioning, beds, a canteen, a disco and a bar or sports facilities."), ("Malapit lang ang Basilica del Santo Niño sa hotel namin kaya hindi na namin kailangang magkotse.", "The Basilica del Santo Niño is near our hotel so we no longer needed to take a car."), ("Kung marami ang sasama sa biyahe natin, mas masaya sigurong magbus na lang ang buong tropa.", "If many will join our trip, it is probably more fun for the whole gang to just take a bus."), ("Isang oras na lang ang magtren mula Tutuban hanggang Clark.", "Riding the train from Tutuban to Clark is now only one hour."), ("Tuwang-tuwa ang kaibigan kong Intsik nang magkalesa kami sa paglilibot sa Intramuros at Binondo.", "My Chinese friend was very happy when we rode a calesa touring Intramuros and Binondo."), ("Puwede ka ring mag-taxi, mag-UBER, o mag-GRAB mula NAIA hanggang Bonifacio Global City kung hindi mo alam mag-commute.", "You can also take a taxi, an Uber or a Grab from NAIA to Bonifacio Global City if you don’t know how to commute."), ("Subukan nating maghabal-habal sa Palawan. Ito raw ang the best kung gusto nating mag-river crossing.", "Let’s try riding a habal-habal in Palawan. They say it is the best if we want river crossing."), ("Magtraysikel na lang tayo papunta sa Tagaytay Ridge.", "Let’s just take a tricycle to Tagaytay Ridge."), ("Mas mabilis kang makakarating sa simbahan kung magdyi-dyip ka.", "You will get to the church faster if you take a jeepney."), ("Kung high tide, puwedeng magbangka o kaya naman maglakad sa lumang footbridge papuntang Caloco Beach.", "At high tide you can take a boat or else walk on the old footbridge to Caloco Beach."), ("Kailangan naming magbalsa upang matawid ang talon sa Pagsanjan.", "We needed to ride a raft to cross the falls at Pagsanjan.")]
